import java.util.*;

class Solution {
  public List<List<Integer>> palindromePairs(String[] words) {
    Map<String, Integer> index = new HashMap<>();
    for (int i = 0; i < words.length; i++) index.put(new StringBuilder(words[i]).reverse().toString(), i);
    List<List<Integer>> ans = new ArrayList<>();
    for (int i = 0; i < words.length; i++) {
      String w = words[i];
      for (int cut = 0; cut <= w.length(); cut++) {
        String left = w.substring(0, cut), right = w.substring(cut);
        // w + other: left must be another word reversed and right a palindrome
        Integer j = index.get(left);
        if (j != null && j != i && isPal(right)) ans.add(Arrays.asList(i, j));
        // other + w: right must be another word reversed and left a palindrome (cut > 0 avoids double counting)
        j = index.get(right);
        if (cut > 0 && j != null && j != i && isPal(left)) ans.add(Arrays.asList(j, i));
      }
    }
    return ans;
  }

  private boolean isPal(String s) {
    for (int i = 0, j = s.length() - 1; i < j; i++, j--) if (s.charAt(i) != s.charAt(j)) return false;
    return true;
  }
}
